	[ 'eans' => [ '7350101312247' ], 'html' => '<p>Denne udgave af Kockums Jernverks pizzaspade kombinerer rustfrit stål med et lædergreb. Brug den til at skyde pizzaen ind på stålet og løfte den ud igen.</p><ul><li>Rustfrit stål</li><li>Lædergreb</li></ul>' ],
	[ 'eans' => [ '5744003850068' ], 'html' => '<p>Hæveklædet måler 45 x 75 cm og er i 100% bomuld med en kraftig stofvægt på 280 gr/m². Det er lavet i professionel kvalitet til både bagerier og hjemmebagere.</p><ul><li>Mål: 45 x 75 cm</li><li>100% bomuld</li><li>Stofvægt: 280 gr/m²</li></ul>' ],
	[ 'eans' => [ '5722002410896' ], 'html' => '<p>Sættet fra Funktion består af en pizzasten på 37,5 cm og en spade af træ, så pizzaen nemt kan skubbes ind på stenen. Resultatet er en sprød bund i stenovnsstil.</p><ul><li>Pizzasten 37,5 cm</li><li>Træspade medfølger</li></ul>' ],
	[ 'eans' => [ '8033866853918' ], 'html' => '<p>Mastrototaros figenmarmelade har en dyb, frugtig sødme, der passer til ost – også på pizzaen, hvor den kan give enkle toppings et overraskende twist.</p>' ],
