	[ 'eans' => [ '5060967395002' ], 'html' => '<p>Med denne brænder kører Ooni Karu 2 Pro på gas. Den sættes blot i porten bagerst på ovnen. Versionen er til EU med 30mbar.</p><ul><li>Til Karu 2 Pro</li><li>EU, 30mbar</li></ul>' ],
